    exit()
S1=0
lst=[]
lst1=[]
ST=Segment_Tree(N,lambda x,y:x+y,0,[1]*N)
finv1=MD.Fact_Inve(N-K-1)
for k in range(K):
    f=MD.Fact(N-2-k)*finv1%mod
    lst.append(f)
    v=ST.Fold(0,P[k])*f%mod
    lst1.append(v)
    S1+=v
    ST[P[k]]-=1
idx=[K+1]*N
for k in range(K):
